import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Ex12MapperProxy {

    interface UserMapper {
        Object selectById(int id);

        Object insertUser(String name);
    }

    interface UserMapperOverload {
        Object select(int id);

        Object select(String code);
    }

    static class Configuration {
        final Map<String, String> statements = new LinkedHashMap<String, String>();
        final List<String> conflicts = new ArrayList<String>();

        void register(String namespace, String id, String sql) {
            String statementId = namespace + "." + id;
            if (statements.containsKey(statementId)) {
                conflicts.add(statementId);
            }
            statements.put(statementId, sql);
        }
    }

    // 复刻 MapperProxy：statementId = 接口全限定名 + "." + 方法名
    static class MapperProxy implements InvocationHandler {
        final Configuration cfg;
        final Class<?> mapperInterface;
        final List<String> trace = new ArrayList<String>();

        MapperProxy(Configuration cfg, Class<?> mapperInterface) {
            this.cfg = cfg;
            this.mapperInterface = mapperInterface;
        }

        public Object invoke(Object proxy, Method method, Object[] args) {
            String statementId = mapperInterface.getName() + "." + method.getName();
            String sql = cfg.statements.get(statementId);
            trace.add(statementId + " -> " + sql + " args="
                    + (args == null ? "[]" : Arrays.toString(args)));
            return sql;
        }
    }

    @SuppressWarnings("unchecked")
    static <T> T getMapper(Configuration cfg, Class<T> type, MapperProxy[] holder) {
        MapperProxy handler = new MapperProxy(cfg, type);
        holder[0] = handler;
        return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] { type }, handler);
    }

    public static void main(String[] args) {
        Configuration cfg = new Configuration();
        String ns = UserMapper.class.getName();
        cfg.register(ns, "selectById", "SELECT id, name FROM t_user WHERE id = ?");
        cfg.register(ns, "insertUser", "INSERT INTO t_user(name) VALUES (?)");

        MapperProxy[] holder = new MapperProxy[1];
        UserMapper mapper = getMapper(cfg, UserMapper.class, holder);
        mapper.selectById(1);
        mapper.insertUser("tom");
        for (String t : holder[0].trace) {
            System.out.println("invoke " + t);
        }
        System.out.println("statements       : " + cfg.statements.size());

        Configuration cfg2 = new Configuration();
        String ns2 = UserMapperOverload.class.getName();
        cfg2.register(ns2, "select", "SELECT * FROM t_user WHERE id = ?");
        cfg2.register(ns2, "select", "SELECT * FROM t_user WHERE code = ?");
        System.out.println("overload conflict: " + (!cfg2.conflicts.isEmpty()));
        System.out.println("conflict ids     : " + cfg2.conflicts);
        System.out.println("kept statement   : " + cfg2.statements.values().iterator().next());
    }
}
